using System;
using System.IO;
using System.IO.Compression;
using System.Text;

public class GzipBase64Decoder
{
    public static void DecodeAndToFile(string base64String, string outputFilePath)
    {
        // 1. 解码
        string decompressedContent = DecompressAndExecute(base64String);

        // 2. 写入文件
        File.WriteAllText(outputFilePath, decompressedContent, Encoding.UTF8);

        Console.WriteLine($"[INFO] 解压内容已写入文件: {outputFilePath}");
    }

    public static string DecompressAndExecute(string base64String, bool executeCode = false)
    {
        try
        {
            // 1. Base64解码为字节数组 
            byte[] compressedBytes = Convert.FromBase64String(base64String);
            Console.WriteLine($"[DEBUG] Base64解码后字节长度: {compressedBytes.Length}");

            // 检查Gzip魔法数字（Magic Number）
            if (compressedBytes.Length < 10 || compressedBytes[0] != 0x1F || compressedBytes[1] != 0x8B)
                throw new InvalidDataException("输入不是合法的Gzip数据");

            // 2. 使用MemoryStream和GZipStream解压
            using (MemoryStream compressedStream = new MemoryStream(compressedBytes))
            using (GZipStream decompressionStream = new GZipStream(compressedStream, CompressionMode.Decompress))
            using (MemoryStream decompressedStream = new MemoryStream())
            {
                decompressionStream.CopyTo(decompressedStream);
                byte[] decompressedBytes = decompressedStream.ToArray();

                // 3. 将解压后的字节转为字符串（假设是UTF-8编码）
                string decompressedText = Encoding.UTF8.GetString(decompressedBytes);
                Console.WriteLine($"[DEBUG] 解压后内容: {decompressedText}");

                // 4. 可选：动态执行代码（类似PowerShell的IEX）
                if (executeCode)
                {
                    // 警告：实际项目中应避免直接执行未经验证的代码！
                    Console.WriteLine("[WARNING] 动态代码执行已启用");
                    // 此处仅为演示，实际可能需要调用C#编译器服务或脚本引擎
                    // 例如使用Roslyn或CSScript库 
                }

                return decompressedText;
            }
        }
        catch (FormatException)
        {
            Console.WriteLine("[ERROR] Base64字符串格式无效");
            throw;
        }
        catch (InvalidDataException)
        {
            Console.WriteLine("[ERROR] Gzip数据格式无效（可能输入不是Gzip压缩数据）");
            throw;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"[ERROR] 其他异常: {ex.Message}");
            throw;
        }
    }

    // 示例调用 
    public static void Main()
    {
        // 示例输入：压缩"Hello World"的Base64字符串（合法Gzip数据）
        string validGzipBase64 = "";
        string validGzipBase641 = "";

        try
        {
            // string result = DecompressAndExecute(validGzipBase64);
            // Console.WriteLine($"最终输出: {result}"); // 应输出 "Hello World"

            DecodeAndToFile(validGzipBase64, "output.txt");
        }
        catch
        {
            Console.WriteLine("处理失败，请检查输入数据");
        }
    }
}